        })->bindTo($reader, PdfReader::class);
        foreach ([$setSourceSha256, $detect, $lineItem, $repair, $dispositions] as $closure) {
            $t->true($closure instanceof \Closure);
        }
        $setSourceSha256(str_repeat('d', 64));

        $source = static fn (
