            float $x1,
            float $y1,
            float $x2,
            float $y2
        ): array => [
            'id' => 'source-' . $index,
            'page' => 1,
            'stream' => 1,
            'text' => $text,
            'sourceGeometryMethod' => 'exact-page-stream-character-offset',
            'sourceGeometry' => [
                'page' => 1,
                'stream' => 1,
                'x1' => $x1,
                'y1' => $y1,
                'x2' => $x2,
                'y2' => $y2,
                'orientation' => 'horizontal',
            ],
        ];
        $sourceItems = [
            $source(
                0,
                'The bellows type is made of aluminum alloy only.',
                318.4954,
                656.3464,
                562.8784,
                668.8464
            ),
            $source(1, '.', 318.4954, 643.8464, 328.4954, 656.3464),
            $source(
                2,
                'Stainless Steel Self-Locking Nut',
                318.4954,
                631.3464,
                453.4954,
                643.8464
            ),
            $source(
                3,
                'The stainless steel nut uses a locking insert for service.',
                318.4954,
                616.8464,
                560.0,
                629.3464
            ),
