        $sameBaselineLeft = [
            'x1' => 100.0,
            'y1' => 300.0,
            'x2' => 130.0,
            'y2' => 312.0,
            'fontSize' => 10.0,
            'forceBlockBreakBefore' => true,
        ];
        $sameBaselineRight = [
            'x1' => 129.5,
            'y1' => 300.0,
            'x2' => 138.0,
            'y2' => 312.0,
