        $orderedProof = $suppressionByText['1. Ordered item keeps • inline symbol.']['evidence'] ?? [];
        $t->same('exact-structural-list-item-occurrence', $orderedProof['method'] ?? null);
        $t->same('ordered', $orderedProof['listType'] ?? null);
