            'page' => 1,
            'stream' => 1,
            'x1' => $x1,
            'y1' => 700.0,
            'x2' => $x2,
            'y2' => 712.0,
        ];
        $items = [
            [
                'id' => 'geometry-marker',
                'page' => 1,
                'stream' => 1,
                'text' => '1.',
                'sourceGeometry' => $geometry(72.0, 82.0),
            ],
            [
                'id' => 'geometry-anchor',
                'page' => 1,
                'stream' => 1,
                'text' => 'Geometry item.',
                'sourceGeometry' => $geometry(90.0, 180.0),
            ],
