        })->bindTo($reader, PdfReader::class);
        $restoreMarkers = (function (array $items, array $sourceItems): array {
            return $this->restoreSourcePdfStandaloneListMarkerPrefixes($items, $sourceItems);
        })->bindTo($reader, PdfReader::class);
