        foreach ([$setSourceSha256, $markInlineMarkers, $exactFallback, $restoreMarkers, $repair, $blocksFromLines] as $closure) {
            $t->true($closure instanceof \Closure);
        }
        $setSourceSha256(str_repeat('7', 64));

        $source = static fn (
            string $id,
            string $text,
            float $x1,
            float $y1,
            float $x2,
            int $globalIndex
        ): array => [
            'id' => $id,
