        $t->true($repairsFor instanceof \Closure);
        $t->true($dispositionsFor instanceof \Closure);
        $setSourceSha256(str_repeat('a', 64));

        $items = [
            ['id' => 'range-river-evidence', 'page' => 1, 'stream' => 3, 'text' => 'A riverbank is nearby.'],
