        $t->same(null, $mastheadRecords[4]['layout']['sourcePdfDisplayHeading'] ?? null);
        $t->same(null, $mastheadRecords[5]['layout']['sourcePdfDisplayHeading'] ?? null);

        $spatialItems = [];
