            preg_replace('/[\s\p{Cc}\p{Cf}]+/u', '', $text) ?? '';
        $record = static function (
            int $index,
            string $text,
            float $x1,
            float $y1,
            float $x2,
            float $y2,
            float $fontSize = 10.0
        ) use ($projection): array {
            return [
                'text' => $text,
                'layout' => [
                    'id' => 'local-label-source-' . $index,
                    'page' => 1,
                    'sourceStream' => 1,
                    'sourcePdfGlobalSourceIndex' => $index,
                    'x1' => $x1,
                    'y1' => $y1,
                    'x2' => $x2,
                    'y2' => $y2,
                    'fontSize' => $fontSize,
                    'sourcePdfExactSourceRanges' => [[
                        'sourceIndex' => $index,
