        ];
        for ($index = 5; $index < 10; $index++) {
            $records[] = $record(
                $index,
                'Ordinary body line ' . $index . ' remains readable.',
                72.0,
                720.0 - ($index - 5) * 24.0,
                390.0,
                730.0 - ($index - 5) * 24.0
            );
