            'sourcePdfSourceIndex' => 15,
            'sourcePdfSourceIndexEnd' => 17,
            'sourcePdfSourceIndexes' => [15, 16, 17],
            'sourcePdfExactRangeFragmentSequence' => true,
            'sourcePdfExactPositionedText' => true,
