        $partialMinorPanel = $minorPanel;
        $partialMinorPanel['sourcePdfExactSourceRanges'][0]['sourceEnd']--;
        $t->same(false, $minorPanelMatches($partialMinorPanel, $minorSourceItems[1], 1));

        $duplicateFallback = $fallback;
